      "observed": "C8 is populated as 1mF/25V in an 0805 capacitor footprint.",
      "expected": "C8 should be 1uF/25V according to the EPD reference circuit specification.",
      "evidence": [
        {
          "source": "spec",
          "quote": "C2 default: 1 µF/25 V | C1/C5/C7/C8/C9/C10 = 1 µF/25 V | Matches default"
        },
